// Per-bench normalization to a [0, 100] composite scale.
//
// • cfElo (FAZ 8.A.3c piecewise replaces prior linear): the linear
//   (elo-1000)/25 mapping under-counted frontier ratings — gpt-5-5's
//   cfElo 1488 mapped to 19.5/100 even though it is the strongest
//   competitive-programming score in the dataset. Three-segment
//   piecewise calibration:
//     [1200, 1600) -> [0, 40)    (entry tier)
//     [1600, 2800) -> [40, 85)   (strong-to-frontier sweep)
//     [2800, 3500) -> [85, 100]  (top of distribution)
// • webDevElo: LMArena WebDev Arena (~950-1300) — linear mapping retained.
// • aaOmni: Artificial Analysis Omniscience (lower is better — measures
//   hallucination rate). Invert so higher composite score = better model.
// Other benches are already on 0-100; returned as-is.
// F1+F2 (2026-05-18): tries State.schema.normalization[key] first (data-driven);
// falls back to hardcoded piecewise/linear/invert logic for backward compat
// (older deploys where sources-whitelist.json was not fetched).
export function normalizeBenchScore(key, value) {
  if (value == null || !Number.isFinite(value)) return null;
  const cfg = (State.schema && State.schema.normalization) || null;
  const entry = cfg && cfg[key];
  if (entry && entry.type) {
    if (entry.type === 'piecewise' && Array.isArray(entry.breakpoints) && Array.isArray(entry.outputs)) {
      const bp = entry.breakpoints, out = entry.outputs;
      if (bp.length >= 2 && out.length === bp.length && value < bp[0]) return out[0];
      for (let i = 0; i < bp.length - 1; i++) {
        if (value < bp[i + 1]) {
          const span = bp[i + 1] - bp[i];
          const gain = out[i + 1] - out[i];
          return out[i] + ((value - bp[i]) / span) * gain;
        }
      }
      return out[out.length - 1];
    }
    if (entry.type === 'linear') {
      const origin = Number(entry.origin) || 0;
      const divisor = Number(entry.divisor) || 1;
      const v = (value - origin) / divisor;
      const lo = Number.isFinite(entry.clampMin) ? entry.clampMin : -Infinity;
      const hi = Number.isFinite(entry.clampMax) ? entry.clampMax : Infinity;
      return Math.max(lo, Math.min(hi, v));
    }
    if (entry.type === 'invert') {
      const max = Number.isFinite(entry.max) ? entry.max : 100;
      return Math.max(0, Math.min(100, max - value));
    }
    if (entry.type === 'inverse-rank') {
      // rank 1 = 100; rank topN = ~2; rank > topN = 0
      const topN = Number(entry.topN) || 50;
      const score = (100 * (topN - value + 1)) / topN;
      return Math.max(0, Math.min(100, score));
    }
  }
  // ── fallback (no schema or unknown type) ──
  if (key === 'cfElo') {
    if (value < 1200) return 0;
    if (value < 1600) return ((value - 1200) / 400) * 40;
    if (value < 2800) return 40 + ((value - 1600) / 1200) * 45;
    if (value < 3500) return 85 + ((value - 2800) / 700) * 15;
    return 100;
  }
  if (key === 'webDevElo') {
    const pct = (value - 950) / 3.5;
    return Math.max(0, Math.min(100, pct));
  }
  if (key === 'aaOmni') {
    return Math.max(0, Math.min(100, 100 - value));
  }
  return value;
}

// 2026-05-18 retune: weights reflect benchmark reliability + discrimination in
// May 2026, not 2025 norms. Key shifts from prior generation:
//   • SWE-bench Verified (sweV) demoted from primary signal — saturated at top
//     (<1.3pp spread), contamination flagged by OpenAI across all frontier
//     models. SWE-bench Pro (swePro) is the new gold standard (top ~56%,
//     standardized SEAL scaffolding, private subset).
//   • Terminal-Bench 2 (tb2) elevated as the de-facto agentic-coding standard
//     (top scores 65-82%, real differentiation).
//   • LiveCodeBench (lcb) — contamination-resistant time-windowed code gen,
//     held as reliable secondary.
//   • GPQA / AIME / MMLU-Pro saturated → reasoning preset shifts heavy to
//     HLE (current frontier ~50% with tools) and ARC-AGI-2 (still discriminates).
//   • τ²-Bench (tau2) is the top multi-turn agentic reliability signal.
//   • MCP-Atlas (mcpA) elevated — Scale AI 2026 frontier MCP eval, becoming
//     a primary agentic discriminator alongside τ²-Bench.
// Each preset's weights sum to 100; coverage is intentionally widened from the
// prior coding-centric anchors so each preset reflects its full domain.
export const DEFAULT_WEIGHTS = {
  swePro: 14, tb2: 11, lcb: 8, hle: 8, tau2: 6, mcpA: 5,
  sweMulti: 5, arcAgi2: 5, tbHard: 4, cfElo: 4, sweV: 4,
  aaCoding: 4, aaAgentic: 4, gpqa: 3, aime26: 3, aaIdx: 3,
  aaOmni: 3, browseComp: 3, bfcl: 3,
};

